INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(17366, 'plPL', 'Intruzi wdarli się do fabryki! Natychmiast uruchomić awaryjny protokół obrony!', 'Intruzi wdarli się do fabryki! Natychmiast uruchomić awaryjny protokół obrony!', 0),
(17913, 'plPL', 'Chronić Mechanar za wszelką cenę!', '', 0),
(18662, 'plPL', 'Przy precyzyjnym kącie i prędkości...', '', 0),
(18716, 'plPL', 'Szukam kogoś do pracy zespołowej...', '', 0),
(18717, 'plPL', 'Czas uzupełnić siłę roboczą.', '', 0),
(18725, 'plPL', 'Wolę wszystkiego doglądać osobiście...', '', 0),
(19059, 'plPL', 'Czekałem na was!', '', 0),
(19952, 'plPL', 'Lepiej zmykajcie, póki możecie.', '', 0),
(19953, 'plPL', 'Nie mówcie, że nie ostrzegałem...', '', 0),
(19954, 'plPL', 'Do licha, ale jestem dobry!', '', 0),
(19955, 'plPL', 'Myślicie, że możecie mi coś zrobić, co? Myślicie, że się was boję?', '', 0),
(19956, 'plPL', 'No dalej, dajcie z siebie wszystko. Wytrzymam!', '', 0),
(19957, 'plPL', 'Łobuzy!', '', 0),
(19959, 'plPL', '', 'Niezbyt cenicie sobie życie, co?', 0),
(19961, 'plPL', '', 'I nie wracajcie!', 0),
(19962, 'plPL', '', 'Endala finel endal!', 0),
(19963, 'plPL', '', 'Myślicie, że wytrzymacie ten żar?', 0),
(19964, 'plPL', '', 'Anar\'endal dracon!', 0),
(19965, 'plPL', '', 'Nie jestem sama.', 0),
(19966, 'plPL', '', 'Anu... bala belore...alon.', 0),
(20029, 'plPL', 'Prymitywna technika, a jednak całkiem skuteczna.', '', 0),
(20030, 'plPL', 'Moje obliczenia nie...', '', 0),
(20031, 'plPL', 'Wynik z góry przesądzony.', '', 0),
(20032, 'plPL', 'Przetwarzanie będzie kontynuowane zgodnie z harmonogramem!', '', 0),
(20033, 'plPL', 'Zostało wam mniej więcej pięć sekund życia.', '', 0),
(20034, 'plPL', 'Przewiduję bolesną śmierć.', '', 0),
(20035, 'plPL', 'Wasza strategia była wadliwa.', '', 0),
(20036, 'plPL', 'Tak, jedyny logiczny wynik.', '', 0),
(20037, 'plPL', 'Dwa razy mierz, raz tnij.', '', 0),
(20038, 'plPL', 'Jeśli moje dzielenie jest poprawne... powinniście być całkiem martwi.', '', 0),
(20039, 'plPL', 'Nieprzewidziana... okoliczność.', '', 0),
(20040, 'plPL', 'Teraz pracujesz dla mnie!', '', 0),
(20041, 'plPL', 'Mamy ścisły harmonogram. Nie będziecie przeszkadzać!', '', 0),
(20042, 'plPL', 'Drobna niedogodność.', '', 0),
(20043, 'plPL', 'Wygląda na to, że przegraliście.', '', 0),
(20044, 'plPL', 'Projekt będzie... kontynuowany.', '', 0),
(20710, 'plPL', '%s groźnie unosi młot...', '', 0);
